function paintDepotSmoke(ctx,age,alpha){if(alpha<=0)return;ctx.save();ctx.fillStyle='#16140f';ctx.globalAlpha=Math.max(0,Math.min(1,alpha));ctx.fillRect(0,0,960,540);ctx.globalAlpha=1;depotEngine?.air.paint(ctx,age,{...fx.battleSmoke,color:'#211f1a',density:100,thickness:140,scale:2,opacity:alpha,seed:92,path:[[-.1,1],[.5,.6],[1.1,-.1]]});ctx.restore()}
